/* Trains & Railroads set additions — cards appended after trains.js.
   (trains.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'trains.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('trains');
  if (!S) return;
  var extra = [{"name":"Orient Express","rarity":"chase","id":"orient-express","subtitle":"Named Trains & Famous Routes","details":"Luxury service first run in 1883 between Paris and Istanbul, whose sleeping and dining cars made it the most famous train name in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Orient_Express_Buchs.jpg?width=1024"},{"name":"Trans-Siberian Express","rarity":"chase","id":"trans-siberian-express","subtitle":"Named Trains & Famous Routes","details":"Service between Moscow and Vladivostok across Russia, covering over 9,000 kilometres and widely described as the longest railway journey anywhere.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trans-Siberian_train._Moscow-Vladivostok.jpg?width=1024"},{"name":"Glacier Express","rarity":"chase","id":"glacier-express","subtitle":"Named Trains & Famous Routes","details":"Panoramic service between Zermatt and St Moritz in the Swiss Alps, marketed as the slowest express train in the world for its scenic pace.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MGB_HGe_4-4_II_mit_Glacier_Express_kurz_vor_Oberalp_Passh%C3%B6he.jpg?width=1024"},{"name":"California Zephyr","rarity":"legendary","id":"california-zephyr","subtitle":"Named Trains & Famous Routes","details":"Service between Chicago and the San Francisco Bay Area famed for Vista-Dome cars and its climb through the Colorado Rockies and Sierra Nevada.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/California_Zephyr_north_of_Green_River.jpg?width=1024"},{"name":"The Ghan","rarity":"legendary","id":"the-ghan","subtitle":"Named Trains & Famous Routes","details":"Service crossing Australia between Adelaide and Darwin, named for Afghan cameleers who pioneered routes through the desert interior country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Journey_Beyond_Rail_Ghan_passenger_train.jpg?width=1024"},{"name":"Bernina Express","rarity":"legendary","id":"bernina-express","subtitle":"Named Trains & Famous Routes","details":"Swiss panoramic service crossing the Landwasser Viaduct and Brusio spiral viaduct on a UNESCO-listed Alpine railway between Chur and Tirano.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brusio_spiral_viaduct.jpg?width=1024"},{"name":"Blue Train (South Africa)","rarity":"legendary","id":"blue-train-south-africa","subtitle":"Named Trains & Famous Routes","details":"Luxury service between Pretoria and Cape Town famous for its royal-blue livery, suites and hotel-grade dining cars on a journey of over 1,600 km.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blue_Train_passes_through_the_Karoo.jpg?width=1024"},{"name":"Rocky Mountaineer","rarity":"legendary","id":"rocky-mountaineer","subtitle":"Named Trains & Famous Routes","details":"Daylight sightseeing service linking Vancouver with Banff, Lake Louise and Jasper, crossing the Canadian Rockies in glass-domed coaches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rocky_Mountaineer_train.jpg?width=1024"},{"name":"Flåm Railway","rarity":"epic","id":"flam-railway","subtitle":"Named Trains & Famous Routes","details":"Norwegian branch line from Myrdal to Flåm, counted among the steepest standard-gauge adhesion railways in the world on its fjord descent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fl%C3%A5msbana.jpg?width=1024"},{"name":"Royal Scotsman","rarity":"epic","id":"royal-scotsman","subtitle":"Named Trains & Famous Routes","details":"Luxury sleeper touring the Scottish Highlands from Edinburgh, famed for castle and estate visits and itineraries through whisky country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Royal_Scotsman_at_Garve_%28geograph_5414361%29.jpg?width=1024"},{"name":"Empire Builder","rarity":"epic","id":"empire-builder","subtitle":"Named Trains & Famous Routes","details":"Service between Chicago and Seattle and Portland following James J. Hill's Great Northern route across the northern plains and Cascades.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ALC-42_heads_into_Wisconsin_Dells.jpg?width=1024"},{"name":"Indian Pacific","rarity":"epic","id":"indian-pacific","subtitle":"Named Trains & Famous Routes","details":"Service crossing Australia between Sydney and Perth, including one of the longest straight stretches of track in the world across the Nullarbor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Indian_Pacific_passenger_train_2025.jpg?width=1024"},{"name":"Eastern & Oriental Express","rarity":"epic","id":"eastern-oriental-express","subtitle":"Named Trains & Famous Routes","details":"Luxury service linking Singapore with Bangkok through Malaysia, crossing jungle, river valleys and the famous bridge country near Kanchanaburi.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern_and_oriental_express_20190401_jb.jpg?width=1024"},{"name":"Maharajas' Express","rarity":"epic","id":"maharajas-express","subtitle":"Named Trains & Famous Routes","details":"Indian luxury touring train linking Delhi with Mumbai, Agra and the grand palace cities of Rajasthan on circular heritage itineraries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maharajas%27_Express_Train.jpg?width=1024"},{"name":"Seven Stars in Kyushu","rarity":"epic","id":"seven-stars-in-kyushu","subtitle":"Named Trains & Famous Routes","details":"Japanese luxury cruise train touring Kyushu in seven cars, named for the island's seven prefectures and designed as a rolling ryokan hotel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JR_%E3%81%AA%E3%81%AA%E3%81%A4%E6%98%9F_Seven_Stars_in_Kyushu%2C_%E7%AB%B9%E4%B8%8B%E9%A7%85_%2820250201%29.jpg?width=1024"},{"name":"Coast Starlight","rarity":"rare","id":"coast-starlight","subtitle":"Named Trains & Famous Routes","details":"Service between Seattle and Los Angeles famed for long stretches of Pacific coastline running, notably south of Santa Barbara in California.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coast_Starlight_crossing_the_Santa_Ynez_River%2C_July_2019.jpg?width=1024"},{"name":"Southwest Chief","rarity":"rare","id":"southwest-chief","subtitle":"Named Trains & Famous Routes","details":"Service between Chicago and Los Angeles following much of the historic Santa Fe Chief route across Kansas and the desert Southwest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southwest_Chief_at_Laguna%2C_February_2020.jpg?width=1024"},{"name":"The Canadian","rarity":"rare","id":"the-canadian","subtitle":"Named Trains & Famous Routes","details":"Service between Toronto and Vancouver formed of stainless Budd cars, crossing the Canadian Shield, the Prairies and the Rocky Mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Thecanadiannearjasper.jpg?width=1024"},{"name":"TranzAlpine","rarity":"rare","id":"tranzalpine","subtitle":"Named Trains & Famous Routes","details":"Service between Christchurch and Greymouth crossing New Zealand's Southern Alps through the Otira Tunnel and the Waimakariri Gorge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arthur%27s_Pass_Tranzscenic_Train.jpg?width=1024"},{"name":"Kuranda Scenic Railway","rarity":"rare","id":"kuranda-scenic-railway","subtitle":"Named Trains & Famous Routes","details":"Queensland climb from Cairns to Kuranda through the Barron Gorge, crossing high bridges and passing waterfalls amid dense rainforest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kuranda_Railway_Station_and_train_QUT-7258-1.jpg?width=1024"},{"name":"Palace on Wheels","rarity":"rare","id":"palace-on-wheels","subtitle":"Named Trains & Famous Routes","details":"Rajasthan luxury touring train modelled on the private carriages of former maharajas, visiting forts, palaces and desert cities from Delhi.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Palace_on_Wheels_luxury_train_at_Jaipur_India.jpg?width=1024"},{"name":"Pride of Africa","rarity":"rare","id":"pride-of-africa","subtitle":"Named Trains & Famous Routes","details":"Rovos Rail luxury service linking Pretoria with Cape Town, Victoria Falls and Dar es Salaam in wood-panelled vintage-style trains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rovos_Rail_Capital_Park_Station.jpg?width=1024"},{"name":"Twilight Express Mizukaze","rarity":"rare","id":"twilight-express-mizukaze","subtitle":"Named Trains & Famous Routes","details":"Japanese luxury sleeper touring western Honshu and the Seto Inland Sea coast from Kyoto and Osaka, with panoramic lounge and dining cars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Series87_TWILIGHT-EXPRESS-MIZUKAZE.jpg?width=1024"},{"name":"Andean Explorer","rarity":"rare","id":"andean-explorer","subtitle":"Named Trains & Famous Routes","details":"Peruvian sleeper service linking Cusco, Puno and Arequipa across the high Altiplano, travelling at over 4,000 metres above sea level.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_Andean_Explorer_%2833142795161%29.jpg?width=1024"},{"name":"El Chepe","rarity":"rare","id":"el-chepe","subtitle":"Named Trains & Famous Routes","details":"Chihuahua al Pacífico service through Mexico's Copper Canyon, crossing dozens of bridges and tunnels on its climb from the coast to the sierra.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chepe_Divisadero.jpg?width=1024"},{"name":"Hiram Bingham","rarity":"rare","id":"hiram-bingham","subtitle":"Named Trains & Famous Routes","details":"Luxury day service from Cusco toward Machu Picchu, named for the explorer Hiram Bingham, who publicised the Inca citadel to the world in 1911.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hiram_Bingham_Perurail_-_linea_Cusco-Machu_Picchu_-_2009-01-06_-_Jorge_Lascar.jpg?width=1024"},{"name":"Tren a las Nubes","rarity":"rare","id":"tren-a-las-nubes","subtitle":"Named Trains & Famous Routes","details":"Argentine Train to the Clouds climbing from Salta into the Andes, crossing the La Polvorilla viaduct at over 4,200 metres above sea level.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tren_nubes_trenesarg.jpg?width=1024"},{"name":"City of New Orleans","rarity":"uncommon","id":"city-of-new-orleans","subtitle":"Named Trains & Famous Routes","details":"Service between Chicago and New Orleans along the Mississippi valley, immortalised in song as the train called the City of New Orleans.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The_City_Of_New_Orleans_Train_%40_Champaign_Urbana_Illinois._-_panoramio.jpg?width=1024"},{"name":"Crescent","rarity":"uncommon","id":"crescent-amtrak","subtitle":"Named Trains & Famous Routes","details":"Service between New York and New Orleans through Atlanta and the Piedmont, heir to the Southern Railway's famous Southern Crescent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak_20_Cook_Springs%2C_AL_3-14-15_%2816826581145%29.jpg?width=1024"},{"name":"Lake Shore Limited","rarity":"uncommon","id":"lake-shore-limited","subtitle":"Named Trains & Famous Routes","details":"Service linking New York and Boston with Chicago, skirting the Hudson River and the southern shore of Lake Erie through upstate New York.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Shore_Limited_Train_49_on_08_12_08_enters_Croton_Harmon.jpg?width=1024"},{"name":"Auto Train","rarity":"uncommon","id":"auto-train","subtitle":"Named Trains & Famous Routes","details":"Service between Virginia and Florida carrying passengers together with their cars in enclosed auto carriers, Amtrak's longest train formation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak_Auto_Train_52_Passing_Through_Guinea_Station%2C_Virginia.jpg?width=1024"},{"name":"Adirondack","rarity":"uncommon","id":"adirondack","subtitle":"Named Trains & Famous Routes","details":"Service between New York and Montreal running up the Hudson valley and along Lake Champlain, beneath the Adirondack Mountains of New York.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Saratoga_Springs_Rail_Station_%E2%80%93_Adirondack_Train_02.jpg?width=1024"},{"name":"Caledonian Sleeper","rarity":"uncommon","id":"caledonian-sleeper","subtitle":"Named Trains & Famous Routes","details":"Overnight service between London and Scotland, splitting for Edinburgh, Glasgow, Aberdeen, Inverness and Fort William in the Highlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caledonian_Sleeper_at_Fort_William_-_geograph.org.uk_-_5354948.jpg?width=1024"},{"name":"Night Riviera","rarity":"uncommon","id":"night-riviera","subtitle":"Named Trains & Famous Routes","details":"Sleeper service between London Paddington and Penzance, maintaining an overnight link between the capital and Cornwall in the far southwest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/57603_Night_Riviera_Sleeper_at_London_Paddington_to_Penzance_1C99_%2826721388160%29.jpg?width=1024"},{"name":"Jungfrau Railway","rarity":"uncommon","id":"jungfrau-railway","subtitle":"Named Trains & Famous Routes","details":"Swiss rack railway climbing inside the Eiger to Jungfraujoch, the highest station in Europe, with panoramic views over the Aletsch Glacier.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jungfrau_railway_train_at_KS.JPG?width=1024"},{"name":"Gornergrat Railway","rarity":"uncommon","id":"gornergrat-railway","subtitle":"Named Trains & Famous Routes","details":"Swiss rack railway from Zermatt to Gornergrat, climbing to open views of the Matterhorn and the glaciers around the Monte Rosa massif.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gornergrat_railway.JPG?width=1024"},{"name":"Centovalli Railway","rarity":"uncommon","id":"centovalli-railway","subtitle":"Named Trains & Famous Routes","details":"Narrow-gauge line of a hundred valleys linking Locarno in Switzerland with Domodossola in Italy, crossing scores of bridges and viaducts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ABe_4-8_Intragna_240613_D34.jpg?width=1024"},{"name":"Settle-Carlisle Line","rarity":"uncommon","id":"settle-carlisle-line","subtitle":"Named Trains & Famous Routes","details":"English Pennine route crossing the Ribblehead Viaduct between Settle and Carlisle, saved from closure after a famous public campaign.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/777_SIR_LAMIEL_runs_off_Batty_Moss_Viaduct.jpg?width=1024"},{"name":"Bergen Line","rarity":"uncommon","id":"bergen-line","subtitle":"Named Trains & Famous Routes","details":"Line between Oslo and Bergen crossing Norway's Hardangervidda plateau, described as the highest main line railway in northern Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/NSB_El_18_2245_Tunga.jpg?width=1024"},{"name":"Qinghai-Tibet Railway","rarity":"uncommon","id":"qinghai-tibet-railway","subtitle":"Named Trains & Famous Routes","details":"High-altitude line to Lhasa crossing the Tanggula Pass, the highest railway crossing in the world, with pressurised trains for the thin air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Qingzang_railway_Train_01.jpg?width=800"},{"name":"Semmering Railway","rarity":"uncommon","id":"semmering-railway","subtitle":"Named Trains & Famous Routes","details":"Austrian mountain line over the Semmering Pass built with stone viaducts and tunnels, a pioneering Alpine crossing opened in the 1850s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Breitenstein_-_Semmeringbahn_-_Kalte-Rinne-Viadukt_mit_Regionalzug_-_1.jpg?width=1024"},{"name":"West Highland Line","rarity":"uncommon","id":"west-highland-line","subtitle":"Named Trains & Famous Routes","details":"Route between Glasgow and Fort William and Mallaig, crossing Rannoch Moor and the curved Glenfinnan Viaduct above Loch Shiel in Scotland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jacobite_on_Glenfinnan_Viaduct_2_20211024.jpg?width=1024"},{"name":"La Trochita","rarity":"uncommon","id":"la-trochita","subtitle":"Named Trains & Famous Routes","details":"Old Patagonian Express narrow-gauge line in Argentina, made famous beyond Patagonia by Paul Theroux's travel account of the same name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ferrocarril_La_Trochita_04.JPG?width=1024"},{"name":"Konkan Railway","rarity":"uncommon","id":"konkan-railway","subtitle":"Named Trains & Famous Routes","details":"Indian west-coast line through the foothills of the Western Ghats, built with hundreds of bridges and tunnels along the Arabian Sea coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CSTM_-_MAJN_SF_%2828149592180%29.jpg?width=1024"},{"name":"Dovre Line","rarity":"uncommon","id":"dovre-line","subtitle":"Named Trains & Famous Routes","details":"Line between Oslo and Trondheim running through the Gudbrandsdalen valley and over the rugged Dovrefjell mountains in central Norway.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dovrebanen_km361_Fokstua_no-nb_digifoto_20190624_00007_NB_NKF_06_01_012.jpg?width=1024"},{"name":"Northeast Regional","rarity":"common","id":"northeast-regional","subtitle":"Named Trains & Famous Routes","details":"Amtrak's busiest service family, linking Boston, New York and Washington with cities in Virginia along the busy Northeast Corridor route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak_627_with_a_Northeast_Regional_in_Madison%2C_Connecticut%2C_April_2015.jpg?width=1024"},{"name":"Pacific Surfliner","rarity":"common","id":"pacific-surfliner","subtitle":"Named Trains & Famous Routes","details":"Southern California coastal service linking San Diego, Los Angeles and San Luis Obispo, with long stretches running beside the Pacific Ocean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak_Pacific_Surfliner_Siemens_Charger_SC-44_No._2118_-_February_2022.jpg?width=1024"},{"name":"Capitol Corridor","rarity":"common","id":"capitol-corridor","subtitle":"Named Trains & Famous Routes","details":"Northern California intercity service linking Sacramento with Oakland, San Jose and Auburn, running beside San Francisco Bay for part of its route.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Capitol_Corridor_train_crossing_Alameda_Creek%2C_April_2024.JPG?width=1024"},{"name":"Pennsylvanian","rarity":"common","id":"pennsylvanian","subtitle":"Named Trains & Famous Routes","details":"Service between New York and Pittsburgh crossing Pennsylvania, climbing the Alleghenies over the famous Horseshoe Curve near Altoona.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak_Pennsylvanian_approaching_Altoona%2C_August_2021.jpg?width=1024"},{"name":"Carolinian","rarity":"common","id":"carolinian","subtitle":"Named Trains & Famous Routes","details":"Daytime service between New York and Charlotte through Virginia and the Carolinas, supported by the state of North Carolina since the 1990s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carolinian_High_Point.jpg?width=1024"},{"name":"Palmetto","rarity":"common","id":"palmetto","subtitle":"Named Trains & Famous Routes","details":"Service between New York and Savannah serving the coastal cities of the Carolinas and Georgia, named for the palmetto trees of the South.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Southbound_Palmetto_arriving_at_Fredericksburg_station%2C_December_2018.jpeg?width=1024"},{"name":"Silver Star","rarity":"common","id":"silver-star","subtitle":"Named Trains & Famous Routes","details":"Service between New York and Miami running through the Carolinas and Georgia into central Florida, part of Amtrak's Silver Service family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak_Silver_Star_92_in_SOP.jpg?width=1024"},{"name":"Empire Service","rarity":"common","id":"empire-service","subtitle":"Named Trains & Famous Routes","details":"Corridor service between New York and Niagara Falls running up the Hudson valley through Albany, the state capital of New York state.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Briarcliff_Manor_Amtrak_P32DM_707.jpg?width=1024"},{"name":"Keystone Service","rarity":"common","id":"keystone-service","subtitle":"Named Trains & Famous Routes","details":"Electric service between New York and Harrisburg over Amtrak's Keystone Corridor in Pennsylvania, a former Pennsylvania Railroad main line.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastbound_Keystone_Service_train_at_Lancaster_station%2C_May_2018.jpg?width=1024"},{"name":"Amtrak Cascades","rarity":"common","id":"amtrak-cascades","subtitle":"Named Trains & Famous Routes","details":"Pacific Northwest service linking Eugene, Portland and Seattle with Vancouver, British Columbia, using distinctive Talgo trainsets.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak_Cascades_arriving_at_Vancouver_WA%2C_August_2021.jpg?width=1024"},{"name":"Hiawatha","rarity":"common","id":"hiawatha","subtitle":"Named Trains & Famous Routes","details":"Amtrak corridor train linking Chicago and Milwaukee in about ninety minutes, a short-distance service with frequent departures each day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak%20Hiawatha%20at%20Glenview%20September%202025.jpg?width=1024"},{"name":"Golden Arrow","rarity":"common","id":"golden-arrow","subtitle":"Named Trains & Famous Routes","details":"Historic boat train linking London and Paris via Dover and Calais, paired with the French Flèche d'Or and dressed in Pullman luxury.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fleche%20d%27Or%2C%20Golden%20Arrow%20train%2C%20Paris.jpg?width=1024"},{"name":"Brighton Belle","rarity":"common","id":"brighton-belle","subtitle":"Named Trains & Famous Routes","details":"All-Pullman electric train between London Victoria and Brighton, a glamorous seaside service famed for serving kippers at breakfast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BB%20at%20Purley%20Oaks%20%281964%29.jpg?width=1024"},{"name":"Cornish Riviera Express","rarity":"common","id":"cornish-riviera-express","subtitle":"Named Trains & Famous Routes","details":"Named express from London Paddington to Penzance that helped make Cornwall a holiday destination, running the length of the West Country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Royal%20Albert%20Bridge%20-%20fGWR%2043149%20down%20Cornish%20Riviera.JPG?width=1024"},{"name":"Rheingold","rarity":"common","id":"rheingold","subtitle":"Named Trains & Famous Routes","details":"Luxury Rhine valley express linking the Netherlands with Switzerland, famed for cream and violet cars and panoramic views of the river gorge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bundesarchiv%20Bild%20102-10452%2C%20Rheingold-Express.jpg?width=1024"},{"name":"Trans-Europe Express","rarity":"common","id":"trans-europe-express","subtitle":"Named Trains & Famous Routes","details":"Former network of first-class-only diesel and electric trains linking business centres across western Europe in speed and comfort.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/00%201997%20TEE%20-%20Category%20DB%20class%20VT%2011.5.jpg?width=1024"},{"name":"Puffing Billy Railway","rarity":"common","id":"puffing-billy-railway","subtitle":"Named Trains & Famous Routes","details":"Narrow-gauge steam railway in Victoria's Dandenong Ranges, famed for open carriages where passengers sit on the sills with legs dangling out.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Puffing%20Billy%20%283708462529%29.jpg?width=1024"},{"name":"Downeaster","rarity":"common","id":"downeaster","subtitle":"Named Trains & Famous Routes","details":"Amtrak service linking Boston with Portland and Brunswick in Maine, a New England corridor train serving coastal and university towns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amtrak%20Downeaster%20approaching%20Boston%20North%20Station%20September%202024%204.jpg?width=1024"},{"name":"Kyle Line","rarity":"common","id":"kyle-line","subtitle":"Named Trains & Famous Routes","details":"Scenic Highland line from Inverness to Kyle of Lochalsh, crossing lochs, moorland and mountain passes on the way to the Isle of Skye.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20train%20for%20Kyle%20of%20Lochalsh%20-%20geograph.org.uk%20-%207777097.jpg?width=1024"},{"name":"Inlandsbanan","rarity":"common","id":"inlandsbanan","subtitle":"Named Trains & Famous Routes","details":"Swedish inland railway running north from Kristinehamn to Gällivare through forests, lakes and small towns far from the coastal main lines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Inlandsbanan%20Train%20IBAB.jpg?width=1024"},{"name":"Grand Central Terminal","rarity":"legendary","id":"grand-central-terminal","subtitle":"Stations","details":"Beaux-Arts terminal in Midtown Manhattan opened in 1913, famed for a celestial ceiling, vast main concourse and four-faced opal clock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Central%20Station%20Main%20Concourse%20Jan%202006.jpg?width=1024"},{"name":"St Pancras International","rarity":"legendary","id":"st-pancras-international","subtitle":"Stations","details":"Victorian Gothic London terminus opened in 1868, famed for a vast single-span trainshed standing directly beside the Midland Grand Hotel.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St%20Pancras%20Railway%20Station%202012-06-23.jpg?width=1024"},{"name":"Tokyo Station","rarity":"legendary","id":"tokyo-station","subtitle":"Stations","details":"Red-brick Marunouchi station building in Tokyo opened in 1914, a three-storey design by Tatsuno Kingo crowned with restored domes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Marunouchi%20Central%20Plaza%20with%20blue%20sky%2C%20Tokyo%20station%20and%20Shin-Marunouchi%20Building%2C%20panoramic%20view%20from%20JP%20Tower%2C%20Tokyo%2C%20Japan.jpg?width=1024"},{"name":"Gare du Nord","rarity":"legendary","id":"gare-du-nord","subtitle":"Stations","details":"Paris terminus opened in 1864 behind a neoclassical facade crowned by statues representing the European cities served from its platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gare%20Du%20Nord%20Interior%2C%20Paris%2C%20France%20-%20Diliff.jpg?width=1024"},{"name":"Antwerpen-Centraal","rarity":"epic","id":"antwerpen-centraal","subtitle":"Stations","details":"Antwerp terminus nicknamed the Railway Cathedral, opened in 1905 with a dome-topped stone hall and tracks stacked on several levels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antwerpen%2C%20centraal%20station%20oeg7051%20IMG%201032%202017-08-27%2010.33.jpg?width=1024"},{"name":"Berlin Hauptbahnhof","rarity":"epic","id":"berlin-hauptbahnhof","subtitle":"Stations","details":"Glass-vaulted central station in Berlin opened in 2006 on the Lehrter Bahnhof site, with main lines stacked on two crossing levels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Berlin%20Hauptbahnhof%2C%20Ostseite%2C%20170430%2C%20ako.jpg?width=1024"},{"name":"Chhatrapati Shivaji Terminus","rarity":"epic","id":"chhatrapati-shivaji-terminus","subtitle":"Stations","details":"Victorian Gothic terminus in Mumbai completed in 1887 as Victoria Terminus, blending Gothic Revival forms with Indian craftsmanship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chhatrapati%20Shivaji%20Terminus%20%28Victoria%20Terminus%29.jpg?width=1024"},{"name":"King's Cross Station","rarity":"epic","id":"kings-cross-station","subtitle":"Stations","details":"London terminus opened in 1852 behind twin arched trainsheds, famed for a sweeping Western Concourse and the Platform 9¾ attraction.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/King%27s%20Cross%20Station%20Euston%20Road%202012-05-27.jpg?width=1024"},{"name":"Milano Centrale","rarity":"epic","id":"milano-centrale","subtitle":"Stations","details":"Monumental Milan terminus opened in 1931, mixing Liberty and Art Deco forms across vast marble halls and soaring steel vaults inside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Milano%20Centrale%202022-09-28%2001.jpg?width=1024"},{"name":"Chicago Union Station","rarity":"epic","id":"chicago-union-station","subtitle":"Stations","details":"Beaux-Arts Chicago terminus opened in 1925, centred on a skylit Great Hall ringed by tall Corinthian columns and marble staircases.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chicago%20Union%20Station%2C%20Great%20Hall.jpg?width=1024"},{"name":"Paddington Station","rarity":"rare","id":"paddington-station","subtitle":"Stations","details":"London terminus opened in 1854 to Isambard Kingdom Brunel's design, with a three-span glazed roof and a statue of Paddington Bear.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/London%20paddington%20station%20trainshed%20interior%202025%20dllu.jpg?width=1024"},{"name":"Gare de Lyon","rarity":"rare","id":"gare-de-lyon","subtitle":"Stations","details":"Paris terminus rebuilt for the 1900 Exposition, noted for a tall clock tower and the ornate Train Bleu restaurant above the concourse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Paris%20Gare%20de%20Lyon%20Sep%202017.jpg?width=1024"},{"name":"Los Angeles Union Station","rarity":"rare","id":"los-angeles-union-station","subtitle":"Stations","details":"Mission Revival and Streamline Moderne terminus in Los Angeles opened in 1939, the last of the great American railway stations built.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Los%20Angeles%20%28California%2C%20USA%29%2C%20Union%20Station%20--%202012%20--%204938.jpg?width=1024"},{"name":"Washington Union Station","rarity":"rare","id":"washington-union-station","subtitle":"Stations","details":"Beaux-Arts terminus in Washington, D.C. opened in 1907, Daniel Burnham's marble gateway to the capital near the United States Capitol.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/12-07-13-washington-by-RalfR-62.jpg?width=1024"},{"name":"Sydney Central Station","rarity":"rare","id":"sydney-central-station","subtitle":"Stations","details":"Sandstone terminus in Sydney opened in 1906, the largest station in New South Wales and recognised by a landmark sandstone clock tower.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Central%20railway%20station%2C%20Sydney%2C%202022%2C%2012.jpg?width=1024"},{"name":"Helsinki Central Station","rarity":"rare","id":"helsinki-central-station","subtitle":"Stations","details":"Granite terminus in Helsinki opened in 1919 to Eliel Saarinen's design, flanked by pairs of stone figures holding spherical lanterns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Estaci%C3%B3n%20central%20de%20FF.CC.%20de%20Helsinki%2C%20Finlandia%2C%202012-08-14%2C%20DD%2005.JPG?width=1024"},{"name":"Kyoto Station","rarity":"rare","id":"kyoto-station","subtitle":"Stations","details":"Futuristic station building in Kyoto opened in 1997, a vast atrium of steel and glass rising in broad terraces above the platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kyoto%20Station%20exterior%202018-03-11.jpeg?width=1024"},{"name":"Toronto Union Station","rarity":"rare","id":"toronto-union-station","subtitle":"Stations","details":"Beaux-Arts terminus in Toronto opened in 1927, fronted by a long stone colonnade and centred on a coffered, barrel-vaulted Great Hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Union%20Station%20Toronto%20August%202017%2001.jpg?width=1024"},{"name":"Amsterdam Centraal","rarity":"rare","id":"amsterdam-centraal","subtitle":"Stations","details":"Grand Neo-Renaissance terminus in Amsterdam opened in 1889 on artificial islands in the IJ, designed by noted architect Pierre Cuypers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amsterdam%20%28NL%29%2C%20Centraal%20Station%20--%202015%20--%207265.jpg?width=1024"},{"name":"Flinders Street Station","rarity":"rare","id":"flinders-street-station","subtitle":"Stations","details":"Edwardian terminus in Melbourne opened in 1910, recognised by its yellow facade, green copper dome and a row of famous platform clocks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melbourne%20%28AU%29%2C%20Flinders%20Street%20Railway%20Station%20--%202019%20--%20202623.jpg?width=1024"},{"name":"Waterloo Station","rarity":"uncommon","id":"waterloo-station","subtitle":"Stations","details":"London terminus first opened in 1848 and rebuilt into the early 1900s, a vast station long ranked among Britain's largest by platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Concourse%20at%20Waterloo%20Station%2C%20London%20SE1%20-%20geograph.org.uk%20-%205206597.jpg?width=1024"},{"name":"Victoria Station, London","rarity":"uncommon","id":"victoria-station-london","subtitle":"Stations","details":"London terminus opened in 1860 in two separate halves, later unified as the gateway for trains to Brighton, Dover and the south coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/London%20Victoria%20Station.jpg?width=1024"},{"name":"Euston Station","rarity":"uncommon","id":"euston-station","subtitle":"Stations","details":"London terminus opened in 1837 as the capital's first intercity station; a grand Doric arch stood there until demolition in the 1960s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Euston%20station%2C%20London%2C%20August%202021.jpg?width=1024"},{"name":"Edinburgh Waverley","rarity":"uncommon","id":"edinburgh-waverley","subtitle":"Stations","details":"Station set in a valley below Edinburgh Castle, rebuilt around the turn of the 1900s and named for Sir Walter Scott's Waverley novels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Edinburgh%20Waverley%20Station-20110903-RM-161203.jpg?width=1024"},{"name":"Liverpool Lime Street","rarity":"uncommon","id":"liverpool-lime-street","subtitle":"Stations","details":"Terminus in central Liverpool opened in 1836, with a curved trainshed added in the 1860s and 1870s behind a grand station hotel frontage.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frontage%20of%20Liverpool%20Lime%20Street%20railway%20station.jpg?width=1024"},{"name":"Manchester Piccadilly","rarity":"uncommon","id":"manchester-piccadilly","subtitle":"Stations","details":"Manchester terminus opened in 1842 as Store Street, combining a Victorian trainshed with a glass-fronted concourse rebuilt in the 2000s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manchester%20Piccadilly%20station%20MMB%2041%20185135.jpg?width=1024"},{"name":"York Station","rarity":"uncommon","id":"york-station","subtitle":"Stations","details":"Curved through station in York opened in 1877 with thirteen platforms, once ranked among the largest stations anywhere in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/York%20Trainshed%20%28103739443%29.jpg?width=1024"},{"name":"Bristol Temple Meads","rarity":"uncommon","id":"bristol-temple-meads","subtitle":"Stations","details":"Bristol terminus opened in 1840 as Brunel's western terminus, its Tudor-style facade fronting a trainshed added several decades later.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Architecture%20of%20Bristol%20Temple%20Meads%20-%20DSC%201568.jpg?width=1024"},{"name":"Glasgow Central","rarity":"uncommon","id":"glasgow-central","subtitle":"Stations","details":"Glasgow terminus opened in 1879 and carried over Argyle Street on the bridge nicknamed the Hielanman's Umbrella by generations of local people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/16-11-15-Bahnhof%20Glasgow%20Central-RR2%207029.jpg?width=1024"},{"name":"Shinjuku Station","rarity":"uncommon","id":"shinjuku-station","subtitle":"Stations","details":"Tokyo interchange first opened in 1885, grown into a vast and complex multi-line hub ringed by department stores, offices and bus terminals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Shinjuku%20Station%20at%20morning.jpg?width=1024"},{"name":"Osaka Station","rarity":"uncommon","id":"osaka-station","subtitle":"Stations","details":"Osaka gateway first opened in 1874, rebuilt as Osaka Station City with a vast roofed atrium spanning high above the tracks and platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JR%20Osaka%20Station%2020151226.JPG?width=1024"},{"name":"Sapporo Station","rarity":"uncommon","id":"sapporo-station","subtitle":"Stations","details":"Hokkaido gateway in Sapporo, rebuilt in elevated form in 1988 with the tall JR Tower building added directly over the station in 2003.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/JR%20Sapporo%20Sta03n3200.jpg?width=1024"},{"name":"Seoul Station","rarity":"uncommon","id":"seoul-station","subtitle":"Stations","details":"Seoul terminus whose Renaissance-style old station building opened in 1925, standing beside a large modern high-speed railway station.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seoul-station-20181122-072342.jpg?width=1024"},{"name":"Wien Hauptbahnhof","rarity":"uncommon","id":"wien-hauptbahnhof","subtitle":"Stations","details":"Vienna main station fully opened in 2015, a through station with a distinctive pleated diamond roof over all of its island platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Estaci%C3%B3n%20central%20de%20FF.CC.%2C%20Viena%2C%20Austria%2C%202020-02-01%2C%20DD%2010.jpg?width=1024"},{"name":"Zürich Hauptbahnhof","rarity":"uncommon","id":"zurich-hauptbahnhof","subtitle":"Stations","details":"Zurich terminus opened in 1847 and rebuilt in 1871, fronted by a grand sandstone hall and a statue of railway pioneer Alfred Escher.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bahnhofshalle%20Zuerich.jpeg?width=1024"},{"name":"München Hauptbahnhof","rarity":"uncommon","id":"munchen-hauptbahnhof","subtitle":"Stations","details":"Munich main station on a railway site used since 1839, rebuilt after wartime damage with a broad trainshed hall over its many platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/HauptbahnhofFassade%20Muenchen-01.jpg?width=1024"},{"name":"Hamburg Hauptbahnhof","rarity":"uncommon","id":"hamburg-hauptbahnhof","subtitle":"Stations","details":"Hamburg main station opened in 1906, an island station with a steel hall spanning the platforms between two tall clock towers at either end.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hamburg%20Hauptbahnhof-20120428-RM-104211.jpg?width=1024"},{"name":"Köln Hauptbahnhof","rarity":"uncommon","id":"koln-hauptbahnhof","subtitle":"Stations","details":"Cologne main station standing beside the cathedral, opened in 1859 and rebuilt in the 1890s with a domed entrance hall and trainshed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2024-04-15-K%C3%B6ln-Hauptbahnhof-3956167A3956.jpg?width=1024"},{"name":"Bath Spa Station","rarity":"common","id":"bath-spa-station","subtitle":"Stations","details":"Brunel station in Bath opened in 1840 on a curved viaduct over the River Avon, built in Jacobean style with gently curved platforms.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bath%20Spa%20railway%20station%20MMB%2015%2043127.jpg?width=1024"},{"name":"Cambridge Station","rarity":"common","id":"cambridge-station","subtitle":"Stations","details":"Station in Cambridge opened in 1845 with an unusually long single through platform and an elegant Italianate arcade along the facade.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cambridge%20railway%20station%20MMB%2010%20365515.jpg?width=1024"},{"name":"Oxford Station","rarity":"common","id":"oxford-station","subtitle":"Stations","details":"Station in Oxford first opened in 1852 west of the city centre, rebuilt repeatedly as busy rail links to London and the Midlands grew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Entrance%20to%20Oxford%20Railway%20Station%20-%20geograph.org.uk%20-%202874238.jpg?width=1024"},{"name":"Brighton Station","rarity":"common","id":"brighton-station","subtitle":"Stations","details":"Terminus in Brighton opened in 1841, with an elegant Italianate station building and a curved double-span roof added in 1882 and 1883.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brighton%20station.jpg?width=1024"},{"name":"Exeter St Davids","rarity":"common","id":"exeter-st-davids","subtitle":"Stations","details":"Main station in Exeter opened in 1844 on the Great Western route, where trains for the Riviera Line reverse direction to continue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2008%20at%20Exeter%20St%20Davids%20-%20station%20frontage.jpg?width=1024"},{"name":"Plymouth Station","rarity":"common","id":"plymouth-station","subtitle":"Stations","details":"Plymouth's main station traces to Millbay in 1849, with the present North Road station buildings dating from the 1870s onward in stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plymouth%20%28North%20Road%29%20railway%20station%20-%20geograph.org.uk%20-%203410333.jpg?width=1024"},{"name":"Newcastle Central","rarity":"common","id":"newcastle-central","subtitle":"Stations","details":"Curved station in Newcastle opened in 1850, with a pioneering three-span roof designed by John Dobson and an elegant neoclassical portico.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Portico%2C%20Newcastle%20Central%20Station%2C%2029%20November%202010.jpg?width=1024"},{"name":"Leeds Station","rarity":"common","id":"leeds-station","subtitle":"Stations","details":"Leeds station first opened in 1848, rebuilt in the 1930s and again in the 2000s with a bright new southern entrance concourse for passengers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Concourse%20of%20Leeds%20station%20-%20geograph.org.uk%20-%207419821.jpg?width=1024"},{"name":"Sheffield Station","rarity":"common","id":"sheffield-station","subtitle":"Stations","details":"Sheffield station opened in 1870 with an imposing stone facade on the Midland route, set on a hillside below the Park Hill flats estate.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sheffield%20Railway%20Station.jpg?width=1024"},{"name":"Cardiff Central","rarity":"common","id":"cardiff-central","subtitle":"Stations","details":"Cardiff's main station opened in 1850 as Cardiff General, rebuilt in pale Portland stone during a major 1930s station reconstruction.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cardiff%20Central%20railway%20station%20MMB%2017%20150217.jpg?width=1024"},{"name":"Belfast Lanyon Place","rarity":"common","id":"belfast-lanyon-place","subtitle":"Stations","details":"Belfast terminus opened in 1976 as Belfast Central, renamed Lanyon Place in 2018 after the street address directly outside its entrance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Belfast%20Lanyon%20Place.jpg?width=1024"},{"name":"Dublin Connolly","rarity":"common","id":"dublin-connolly","subtitle":"Stations","details":"Dublin terminus opened in 1844 as Amiens Street station, renamed in 1966 for James Connolly, an Irish leader of the 1916 Easter Rising.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dublin%20Connolly%20Concourse%20%282022-05-30%29.jpg?width=1024"},{"name":"Cork Kent Station","rarity":"common","id":"cork-kent-station","subtitle":"Stations","details":"Cork station opened in 1893 as Glanmire Road, renamed Kent Station in 1966 in honour of executed Easter Rising figure Thomas Kent.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cork%20-%20Cork%20Kent%20railway%20station%20-%2020190525161658.jpg?width=1024"},{"name":"Denver Union Station","rarity":"common","id":"denver-union-station","subtitle":"Stations","details":"Beaux-Arts depot in Denver opened in 1881 and rebuilt after an 1894 fire, centred on a high-ceilinged, light-filled and lofty Great Hall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Denver%20Union%20Station%20-%20June%202022%20-%20Sarah%20Stierch%2001.jpg?width=1024"},{"name":"Kansas City Union Station","rarity":"common","id":"kansas-city-union-station","subtitle":"Stations","details":"Beaux-Arts station in Kansas City opened in 1914, with a grand central hall and a vaulted Grand Plaza for arriving and departing passengers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/KCUnionStation.jpg?width=1024"},{"name":"St. Louis Union Station","rarity":"common","id":"st-louis-union-station","subtitle":"Stations","details":"Romanesque Revival station in St. Louis opened in 1894, once among the busiest American terminals, with a vast trainshed behind the headhouse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/St.%20Louis%20Union%20Station%20%26%20The%20Aloe%20Plaza%20%281983%29.jpg?width=1024"},{"name":"Cincinnati Union Terminal","rarity":"common","id":"cincinnati-union-terminal","subtitle":"Stations","details":"Art Deco terminal in Cincinnati opened in 1933, with a sweeping half-dome rotunda and colourful large-scale Winold Reiss mosaic murals.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Streamline%20Moderne%20-%20Cincinnati%2C%20OH%20-%20Cincinnati%20Union%20Terminal%20%284%29.jpg?width=1024"},{"name":"30th Street Station","rarity":"common","id":"philadelphia-30th-street","subtitle":"Stations","details":"Neoclassical station in Philadelphia opened in 1933, with tall Corinthian porticoes and a coffered ceiling over the main concourse.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/30th%20Street%20Station%20Philadelphia%20July%202016%20001.jpg?width=1024"},{"name":"South Station, Boston","rarity":"common","id":"boston-south-station","subtitle":"Stations","details":"Neoclassical Revival terminal in Boston opened in 1899, uniting several separate railroads under a single large trainshed roof together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/South%20Station%2C%20Boston%2C%20Massachusetts%20April%202022.jpg?width=1024"},{"name":"New Orleans Union Passenger Terminal","rarity":"common","id":"new-orleans-union-passenger-terminal","subtitle":"Stations","details":"Streamline Moderne terminal in New Orleans opened in 1954, uniting the passenger services of a city once split across five stations.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New%20Orleans%20Union%20Passenger%20Terminal%20Feb%202018%20Exterior.jpg?width=1024"},{"name":"Dallas Union Station","rarity":"common","id":"dallas-union-station","subtitle":"Stations","details":"Beaux-Arts station in Dallas opened in 1916 as Union Terminal, fronted by a symmetrical stone facade and rows of tall arched windows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dallas%20Union%20Station%20Wiki%20%281%20of%201%29.jpg?width=1024"},{"name":"Portland Union Station","rarity":"common","id":"portland-union-station","subtitle":"Stations","details":"Queen Anne depot in Portland, Oregon opened in 1896, recognised by a tall clock tower and a famous illuminated Go By Train neon sign.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/UnionStationPortland.jpg?width=1024"},{"name":"Durango & Silverton Narrow Gauge Railroad","rarity":"chase","id":"durango-and-silverton-narrow-gauge-railroad","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge railroad completed in 1882 from Durango to Silverton, Colorado, climbing the Animas River gorge on a route built to serve silver mines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Durango%20%26%20Silverton%20Narrow%20Gauge%20Railroad%20%2839938585813%29.jpg?width=1024"},{"name":"Strasburg Rail Road","rarity":"legendary","id":"strasburg-rail-road","subtitle":"Heritage Railroads & Companies","details":"Pennsylvania short line chartered in 1832, famed for steam excursions through Amish farmland from Strasburg to Paradise in Lancaster County.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Strasburg%20Rail%20Road%20-%20475%20steam%20locomotive%20%28Baldwin%204-8-0%29%20%28Strasburg%2C%20Pennsylvania%2C%20USA%29%2011%20%2826995701481%29.jpg?width=1024"},{"name":"Ffestiniog & Welsh Highland Railways","rarity":"legendary","id":"ffestiniog-and-welsh-highland-railways","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge railways in Snowdonia linking Porthmadog with Blaenau Ffestiniog and Caernarfon, famed for Double Fairlie locomotives and slate traffic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Blaenau%20Ffestiniog%20railway%20station%20MMB%2006%20Merddin%20Emrys.jpg?width=1024"},{"name":"Union Pacific Railroad","rarity":"legendary","id":"union-pacific-railroad","subtitle":"Heritage Railroads & Companies","details":"Company chartered in 1862 that built west from Omaha and met the Central Pacific at Promontory Summit in 1869, completing a transcontinental line.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/UP%20Big%20Boy%204014%20front.jpg?width=1024"},{"name":"Cumbres & Toltec Scenic Railroad","rarity":"epic","id":"cumbres-and-toltec-scenic-railroad","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge railroad over 10,015-foot Cumbres Pass between Chama, New Mexico and Antonito, Colorado, saved from the Rio Grande network in 1970.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cumbres%20%26%20Toltec%20484%20at%20Osier.jpg?width=1024"},{"name":"Cass Scenic Railroad","rarity":"epic","id":"cass-scenic-railroad","subtitle":"Heritage Railroads & Companies","details":"West Virginia logging railroad at Cass, climbed by Shay geared locomotives up switchbacks built to haul timber from the Allegheny highlands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cass%20Scenic%20Railway%20No.%205%20August%202016.jpg?width=1024"},{"name":"Great Western Railway","rarity":"epic","id":"great-western-railway","subtitle":"Heritage Railroads & Companies","details":"British company engineered by Isambard Kingdom Brunel from London toward Bristol and the West, famed for broad gauge and its Swindon Works.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buckfastleigh%20-%201369%20GWR%20shirtbutton%20logo.JPG?width=1024"},{"name":"Darjeeling Himalayan Railway","rarity":"epic","id":"darjeeling-himalayan-railway","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge mountain railway in West Bengal opened in 1881, climbing from the plains to Darjeeling with tight loops and zig-zag reverses.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Darjeeling%20Himalayan%20Railway%2Ctoy%20train%20%282%29.jpg?width=1024"},{"name":"White Pass & Yukon Route","rarity":"epic","id":"white-pass-and-yukon-route","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge railway built from Skagway, Alaska to Whitehorse during the Klondike Gold Rush of 1898 to 1900, climbing the steep White Pass.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/White%20Pass%20and%20Yukon%20Route%20locomotives%20No.%2099%2C%20100%2C%20and%20108%20pulling%20an%20excursion%20train%20over%20a%20bridge%20-%20September%202008%20-%2001.jpg?width=1024"},{"name":"Great Central Railway","rarity":"epic","id":"great-central-railway","subtitle":"Heritage Railroads & Companies","details":"Preserved main line between Loughborough and Leicester, keeping alive a section of the last Victorian main line built into London.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Central%20Railway%20Station%2C%20Loughborough%20-%20geograph.org.uk%20-%204047477.jpg?width=1024"},{"name":"East Lancashire Railway","rarity":"rare","id":"east-lancashire-railway","subtitle":"Heritage Railroads & Companies","details":"Railway between Heywood and Rawtenstall through Bury in Lancashire, following a route first opened in 1846 through the Irwell Valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bury%20Bolton%20Street%20station%20East%20Lancashire%20Railway.jpg?width=1024"},{"name":"Severn Valley Railway","rarity":"rare","id":"severn-valley-railway","subtitle":"Heritage Railroads & Companies","details":"Railway from Kidderminster to Bridgnorth following the River Severn, first opened in 1862 and crossing the river on the Victoria Bridge.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/6695%20Victoria%20Bridge%20Severn%20Valley%20Railway.jpg?width=1024"},{"name":"North Yorkshire Moors Railway","rarity":"rare","id":"north-yorkshire-moors-railway","subtitle":"Heritage Railroads & Companies","details":"Railway from Pickering to Whitby across the North York Moors, following George Stephenson's route first opened over the moorland in 1836.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/North%20Yorkshire%20Moors%20Railway%2C%20Goathland%20-%20geograph.org.uk%20-%202547395.jpg?width=800"},{"name":"Keighley & Worth Valley Railway","rarity":"rare","id":"keighley-and-worth-valley-railway","subtitle":"Heritage Railroads & Companies","details":"Branch line from Keighley to Oxenhope in West Yorkshire, opened in 1867 and famed worldwide as the setting of The Railway Children.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BR%20Standard%20Class%202%20No.%2078022%20approached%20Oakworth%20Station.jpg?width=1024"},{"name":"Bluebell Railway","rarity":"rare","id":"bluebell-railway","subtitle":"Heritage Railroads & Companies","details":"Sussex railway between Sheffield Park and East Grinstead, opened as a heritage line in 1960 and named for the spring bluebells along its banks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bluebell%20Railway%20Horsted%20Keynes%20railway%20station%202016-08-07.jpg?width=1024"},{"name":"West Somerset Railway","rarity":"rare","id":"west-somerset-railway","subtitle":"Heritage Railroads & Companies","details":"Railway from Bishops Lydeard to Minehead in Somerset, the longest standard-gauge heritage line in England, first opened in stages from 1862.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/60019%20Bittern%20approaching%20Watchet%20on%20West%20Somerset%20Railway%20%285951321822%29.jpg?width=1024"},{"name":"Grand Canyon Railway","rarity":"rare","id":"grand-canyon-railway","subtitle":"Heritage Railroads & Companies","details":"Railway from Williams, Arizona to the South Rim of the Grand Canyon, first opened in 1901 and revived for passenger excursions in 1989.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Canyon%20Train%20at%20the%20Grand%20Canyon%20Historic%20Railroad%20Depot%20-%20March%202016.jpg?width=1024"},{"name":"Georgetown Loop Railroad","rarity":"rare","id":"georgetown-loop-railroad","subtitle":"Heritage Railroads & Companies","details":"Colorado narrow-gauge railroad completed in 1884, climbing between Georgetown and Silver Plume over the Devil's Gate High Bridge loop.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Georgetown%20Loop%20%285106737458%29.jpg?width=1024"},{"name":"Mount Washington Cog Railway","rarity":"rare","id":"mount-washington-cog-railway","subtitle":"Heritage Railroads & Companies","details":"Rack railway up Mount Washington in New Hampshire, opened in 1869 as the first mountain-climbing cog railway anywhere in the world.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mount%20Washington%20Steam%20Cog%20Train%20-%20July%202016.jpg?width=1024"},{"name":"Pikes Peak Cog Railway","rarity":"rare","id":"pikes-peak-cog-railway","subtitle":"Heritage Railroads & Companies","details":"Rack railway from Manitou Springs, Colorado to the 14,115-foot summit of Pikes Peak, reaching the top for the first time in 1891 after two years of construction.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pikes%20Peak%20Cog%20Railroad%20near%20the%20Summit.jpg?width=1024"},{"name":"London and North Eastern Railway","rarity":"rare","id":"london-and-north-eastern-railway","subtitle":"Heritage Railroads & Companies","details":"British Big Four company formed in 1923, operator of the Flying Scotsman service and of Nigel Gresley's celebrated Pacific locomotives.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/LNER%20logo%201932.png?width=1024"},{"name":"Pennsylvania Railroad","rarity":"rare","id":"pennsylvania-railroad","subtitle":"Heritage Railroads & Companies","details":"Company chartered in 1846 that grew into a vast eastern network centred on Philadelphia and Altoona, builder of the Horseshoe Curve.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pennsylvania%20Railroad%20GG-1%204899%20at%20Newark%2C%20NJ%20in%20September%201964%20%2826556787184%29.jpg?width=1024"},{"name":"Watercress Line","rarity":"uncommon","id":"watercress-line","subtitle":"Heritage Railroads & Companies","details":"Mid-Hants railway between Alresford and Alton in Hampshire, nicknamed the Watercress Line for the watercress traffic it once carried.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steam%20Engine%2C%20Ropley%20Station%2C%20Watercress%20Line%2C%20Hampshire%20-%20geograph.org.uk%20-%203115100.jpg?width=1024"},{"name":"Kent & East Sussex Railway","rarity":"uncommon","id":"kent-and-east-sussex-railway","subtitle":"Heritage Railroads & Companies","details":"Light railway between Tenterden and Bodiam in Kent, first opened in 1900 under Colonel Stephens as a rural line through hop country.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steam%20Locomotive%20%27Northiam%27%20leaving%20Tenterden%20Railway%20Station%2C%20Kent%20and%20East%20Sussex%20Railway%20-%20geograph.org.uk%20-%205922394.jpg?width=1024"},{"name":"Swanage Railway","rarity":"uncommon","id":"swanage-railway","subtitle":"Heritage Railroads & Companies","details":"Branch line from Norden to Swanage in Dorset, first opened in 1885 and passing the ruined towers of Corfe Castle on its approach to the coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Swanage%20Railway%20and%20Corfe%20Castle%20-%20geograph.org.uk%20-%201793479.jpg?width=1024"},{"name":"Dartmouth Steam Railway","rarity":"uncommon","id":"dartmouth-steam-railway","subtitle":"Heritage Railroads & Companies","details":"Railway from Paignton to Kingswear in Devon, first opened in the 1860s and hugging the Dart estuary opposite the town of Dartmouth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dartmouth%20Steam%20Railway%20at%20Kingswear%20-%20geograph.org.uk%20-%207004020.jpg?width=1024"},{"name":"Llangollen Railway","rarity":"uncommon","id":"llangollen-railway","subtitle":"Heritage Railroads & Companies","details":"Railway along the Dee Valley from Llangollen to Corwen in Wales, first opened in the 1860s beside the fast-flowing River Dee and its wooded banks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Llangollen%20Railway%20Steam%20Locomotive%20in%20the%20River%20Dee%20Valley%20-%20geograph.org.uk%20-%20356104.jpg?width=1024"},{"name":"Talyllyn Railway","rarity":"uncommon","id":"talyllyn-railway","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge railway in Wales opened in 1866 to carry slate from the Bryn Eglwys quarries down the Fathew valley to Tywyn on the coast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Talyllyn%20Railway%20No.%202%20%22Dolgoch%22%20-%20September%202016.jpg?width=1024"},{"name":"Vale of Rheidol Railway","rarity":"uncommon","id":"vale-of-rheidol-railway","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge railway opened in 1902 from Aberystwyth to Devil's Bridge in Wales, climbing steeply through the wooded Rheidol valley.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vale%20of%20Rheidol%20Railway%20-%2052413519769.jpg?width=1024"},{"name":"Snowdon Mountain Railway","rarity":"uncommon","id":"snowdon-mountain-railway","subtitle":"Heritage Railroads & Companies","details":"Rack railway opened in 1896 from Llanberis to the summit of Snowdon, the highest mountain in Wales, climbing on a toothed centre rail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Snowdon%20Mountain%20Railway%20at%20Summit%20station%20-%20geograph.org.uk%20-%206193272.jpg?width=1024"},{"name":"Romney, Hythe & Dymchurch Railway","rarity":"uncommon","id":"romney-hythe-and-dymchurch-railway","subtitle":"Heritage Railroads & Companies","details":"Fifteen-inch gauge railway across Romney Marsh in Kent, opened in 1927 with miniature main-line style Pacific locomotives and double-deck coaches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dymchurch%20station%20geograph-3277377-by-Ben-Brooksbank.jpg?width=1024"},{"name":"Ravenglass & Eskdale Railway","rarity":"uncommon","id":"ravenglass-and-eskdale-railway","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge railway in the Lake District between Ravenglass and Dalegarth, converted to 15-inch gauge as a miniature line in 1915.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/StaughtonManorRailwayColossus.jpg?width=1024"},{"name":"Black Hills Central Railroad","rarity":"uncommon","id":"black-hills-central-railroad","subtitle":"Heritage Railroads & Companies","details":"South Dakota excursion railroad between Hill City and Keystone, home of the 1880 Train and a route through the granite Black Hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vacation%20Black%20Hills%20South%20Dakota%20-%20June%201978.jpg?width=1024"},{"name":"Verde Canyon Railroad","rarity":"uncommon","id":"verde-canyon-railroad","subtitle":"Heritage Railroads & Companies","details":"Arizona excursion railroad from Clarkdale through the Verde Canyon, following a 1912 Santa Fe branch past red-rock cliffs and ruins.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/On%20the%20Verde%20Canyon%20Railroad%20%2833771260478%29.jpg?width=1024"},{"name":"Heber Valley Railroad","rarity":"uncommon","id":"heber-valley-railroad","subtitle":"Heritage Railroads & Companies","details":"Utah excursion railroad from Heber City toward Provo Canyon, following an 1899 Rio Grande branch beside Deer Creek Reservoir and Mount Timpanogos.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Heber%20Valley%20Historic%20Railroad%2C%20Heber%20City%2C%20Utah%20-%2011560626766.jpg?width=1024"},{"name":"Nevada Northern Railway","rarity":"uncommon","id":"nevada-northern-railway","subtitle":"Heritage Railroads & Companies","details":"Nevada railroad built in 1905 and 1906 to serve the Ely copper mines, centred on the East Ely depot, shops, roundhouse and steam fleet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nevada%20Northern%20No.%2040%20Leading%20a%20Train%20Through%20East%20Ely%20-%20February%202020.jpg?width=1024"},{"name":"Sumpter Valley Railroad","rarity":"uncommon","id":"sumpter-valley-railroad","subtitle":"Heritage Railroads & Companies","details":"Oregon narrow-gauge logging railroad first built in the 1890s, running between McEwen and the old gold-mining town of Sumpter in the Blue Mountains.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Engine%20of%20sumpter%20valley%20train%20is%20being%20refueled%20at%20starting%20station%20of%20McEwen%20-%20panoramio.jpg?width=1024"},{"name":"Oregon Coast Scenic Railroad","rarity":"uncommon","id":"oregon-coast-scenic-railroad","subtitle":"Heritage Railroads & Companies","details":"Excursion railroad between Garibaldi and Rockaway Beach on the Oregon coast, formed in 2003 along the shore and tidal flats of Tillamook Bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oregon%20Coast%20Scenic%20Railroad%20-%2090%20%28Baldwin%20Locomotive%20Works%202-8-2%20steam%20locomotive%29%20%28Garibaldi%2C%20Oregon%2C%20USA%29%201.jpg?width=1024"},{"name":"Nilgiri Mountain Railway","rarity":"uncommon","id":"nilgiri-mountain-railway","subtitle":"Heritage Railroads & Companies","details":"Rack railway in Tamil Nadu, India, completed in 1908 from Mettupalayam up to Ooty, climbing with Swiss-built X-Class steam locomotives.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Loco%2037391X%20NMR%20Kalar%20Jul25%20A7CR%2006064.jpg?width=1024"},{"name":"Kalka–Shimla Railway","rarity":"uncommon","id":"kalka-shimla-railway","subtitle":"Heritage Railroads & Companies","details":"Narrow-gauge mountain railway in Himachal Pradesh opened in 1903, climbing through tunnels and viaducts from Kalka to the hill station of Shimla.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20train%20passing%20though%20Barog%20Tunnel%20at%20Barog%20Railway%20Station%2C%20Himachal%20Pradesh.jpg?width=1024"},{"name":"Baltimore and Ohio Railroad","rarity":"common","id":"baltimore-and-ohio-railroad","subtitle":"Heritage Railroads & Companies","details":"Company chartered in 1827 and generally regarded as the first common-carrier railroad in the United States, building west from Baltimore.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Baltimore%20and%20Ohio%204579%20%28F7A%29%20in%20September%201974%20%2822292074050%29.jpg?width=1024"},{"name":"Atchison, Topeka and Santa Fe Railway","rarity":"common","id":"atchison-topeka-and-santa-fe-railway","subtitle":"Heritage Railroads & Companies","details":"Company chartered in 1859 that built across Kansas to California and the Southwest, famed for the blue-and-yellow cross herald and Super Chief.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atchison%2C%20Topeka%20and%20Santa%20Fe%20Railway%20Herald.svg?width=1024"},{"name":"New York Central Railroad","rarity":"common","id":"new-york-central-railroad","subtitle":"Heritage Railroads & Companies","details":"Company formed in 1853 along the Hudson and Mohawk rivers, operator of the Water Level Route and the 20th Century Limited to Chicago.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/New%20York%20Central%20Herald.svg?width=1024"},{"name":"Southern Pacific Railroad","rarity":"common","id":"southern-pacific-railroad","subtitle":"Heritage Railroads & Companies","details":"Western network built from 1865, linking California with Oregon, Arizona and Louisiana under the famous sunset herald and Daylight colours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SP%20herald%20on%20RDC%20SP-10%20as%20the%20Redwood%2C%20January%2030%2C%201971.jpg?width=1024"},{"name":"Chicago, Burlington and Quincy Railroad","rarity":"common","id":"chicago-burlington-and-quincy-railroad","subtitle":"Heritage Railroads & Companies","details":"Midwestern company called the Burlington Route, linking Chicago with Denver, Omaha and the Twin Cities, and pioneer of the Zephyr streamliners.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burlington%20Route%20%E2%80%9CBlack%20Box%E2%80%9D%20Logo.svg?width=1024"},{"name":"Great Northern Railway (US)","rarity":"common","id":"great-northern-railway-us","subtitle":"Heritage Railroads & Companies","details":"Northern transcontinental company completed to Seattle in 1893 under James J. Hill, famed for its mountain-goat herald and Empire Builder name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Northern%20streamliner%20on%20bridge%201964.JPG?width=1024"},{"name":"Northern Pacific Railway","rarity":"common","id":"northern-pacific-railway","subtitle":"Heritage Railroads & Companies","details":"Northern transcontinental railroad chartered in 1864 and completed across Montana to Puget Sound in 1883 under the yin-yang monad herald.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Northern%20Pacific%20caboose%20logo.jpg?width=1024"},{"name":"London Underground","rarity":"common","id":"london-underground","subtitle":"Heritage Railroads & Companies","details":"Metro system begun with the Metropolitan Railway in 1863, unified by the roundel symbol, the Tube map and Edward Johnston's classic typeface.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mosaic%20Underground%20roundel%2C%20Maida%20Vale.jpg?width=1024"},{"name":"London, Midland and Scottish Railway","rarity":"common","id":"london-midland-and-scottish-railway","subtitle":"Heritage Railroads & Companies","details":"British Big Four company formed in 1923, the largest of the four grouped companies by route mileage, centred on Euston station in London.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/London%2C%20Midland%20and%20Scottish%20Railway%20Company%20Logo%20%2815095274827%29.jpg?width=1024"},{"name":"Chesapeake and Ohio Railway","rarity":"common","id":"chesapeake-and-ohio-railway","subtitle":"Heritage Railroads & Companies","details":"Company built from Richmond, Virginia across the Allegheny Mountains to the Ohio River, a major carrier of Appalachian coal and the Chessie cat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/C%26O%20Railway%20Heritage%20Center%20-%20C%26O%20614%20Locomotive%20-%203.JPG?width=1024"},{"name":"Norfolk and Western Railway","rarity":"common","id":"norfolk-and-western-railway","subtitle":"Heritage Railroads & Companies","details":"Virginia coal-hauling company centred on Roanoke, famed for building its own powerful steam locomotives in the Roanoke Shops into the 1950s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Norfolk%20and%20Western%20Railway%20herald.png?width=1024"},{"name":"Denver & Rio Grande Western Railroad","rarity":"common","id":"denver-and-rio-grande-western-railroad","subtitle":"Heritage Railroads & Companies","details":"Mountain railroad company that built narrow-gauge lines across Colorado and standard-gauge routes through the Rockies to Utah and Salt Lake City.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/RoyalGorgeTrain.jpg?width=1024"},{"name":"Western Pacific Railroad","rarity":"common","id":"western-pacific-railroad","subtitle":"Heritage Railroads & Companies","details":"Company completed in 1909 through Feather River Canyon in California as the final link in a transcontinental route to San Francisco Bay.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boxcar%20with%20pink%20Feather%20River%20Route%20logo%20-%205358732696.jpg?width=1024"},{"name":"British Rail","rarity":"common","id":"british-rail","subtitle":"Heritage Railroads & Companies","details":"State operator formed from nationalised railway companies in 1948, identified from 1965 by the famous double-arrow symbol and Rail Alphabet lettering.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Manningtree%20Railway%20Station%20sign%20-%20geograph.org.uk%20-%205882071.jpg?width=1024"},{"name":"Bodmin & Wenford Railway","rarity":"common","id":"bodmin-and-wenford-railway","subtitle":"Heritage Railroads & Companies","details":"Cornish railway between Bodmin Parkway and Boscarne Junction, first opened in 1887 through the wooded valley of the River Camel in Cornwall.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bodmin%20%26%20Wenford%20Railway%2005.jpg?width=1024"},{"name":"Ecclesbourne Valley Railway","rarity":"common","id":"ecclesbourne-valley-railway","subtitle":"Heritage Railroads & Companies","details":"Derbyshire railway between Duffield and Wirksworth, first opened in 1867 through the quiet valley of the River Ecclesbourne near the Peak District.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/An%20Ecclesbourne%20Valley%20Train%20at%20Duffield%20Station%20-%20geograph.org.uk%20-%204207412.jpg?width=1024"},{"name":"Churnet Valley Railway","rarity":"common","id":"churnet-valley-railway","subtitle":"Heritage Railroads & Companies","details":"Staffordshire railway through the Churnet Valley between Cheddleton and Kingsley and Froghall, following river, canal and woodland scenery.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leaving%20Consall%20Station%20-%20geograph.org.uk%20-%201731608.jpg?width=1024"},{"name":"Embsay & Bolton Abbey Steam Railway","rarity":"common","id":"embsay-and-bolton-abbey-steam-railway","subtitle":"Heritage Railroads & Companies","details":"Yorkshire railway first opened in 1888 between Embsay and Bolton Abbey, gateway to the ruins of a 12th-century Augustinian priory.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bolton%20Abbey%20station%20on%20the%20Embsay%20%5E%20Bolton%20Abbey%20Steam%20Railway%20-%20geograph.org.uk%20-%203986968.jpg?width=1024"},{"name":"Tanfield Railway","rarity":"common","id":"tanfield-railway","subtitle":"Heritage Railroads & Companies","details":"Railway in County Durham following a wagonway route dating to 1725, among the oldest railway alignments anywhere in the world, built for coal traffic.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tanfield%20Railway%20-%20No.%202%20approaching%20Andrews%20House%20Station%20-%20geograph.org.uk%20-%208186668.jpg?width=1024"},{"name":"Foxfield Railway","rarity":"common","id":"foxfield-railway","subtitle":"Heritage Railroads & Companies","details":"Staffordshire colliery railway first built in 1893 to serve Foxfield Colliery, climbing steeply from its Caverswall Road station to Dilhorne Park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bellerophon%20on%20the%20Foxfield%20Railway%20-%20geograph.org.uk%20-%205492509.jpg?width=800"},{"name":"Chasewater Railway","rarity":"common","id":"chasewater-railway","subtitle":"Heritage Railroads & Companies","details":"Railway around Chasewater reservoir in Staffordshire, built on former colliery tracks beside the water, its sailing shore and country park.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Train%20on%20the%20causeway%20at%20Chasewater%20Light%20Railway%20-%20geograph.org.uk%20-%204366976.jpg?width=1024"},{"name":"Dean Forest Railway","rarity":"common","id":"dean-forest-railway","subtitle":"Heritage Railroads & Companies","details":"Railway between Lydney and Parkend in the Forest of Dean, following a tramway route first laid out through the ancient woodland in 1810.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20power%20of%20steam-%20departure%20from%20Norchard%2C%20Dean%20Forest%20Railway.jpg?width=1024"},{"name":"Gloucestershire Warwickshire Steam Railway","rarity":"common","id":"gloucestershire-warwickshire-steam-railway","subtitle":"Heritage Railroads & Companies","details":"Cotswolds railway between Cheltenham Race Course and Broadway, first opened in 1904 to 1906 through Toddington, Winchcombe and honey-stone villages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Toddington%20railway%20station%20MMB%2011%2037324%205619.jpg?width=1024"},{"name":"Nene Valley Railway","rarity":"common","id":"nene-valley-railway","subtitle":"Heritage Railroads & Companies","details":"Railway from Peterborough to Yarwell through Nene Park in Cambridgeshire, first opened in 1845 along the green valley of the River Nene.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Swedish%20B%20Class%204-6-0%20locomotive%20at%20Wansford%20station%20on%20the%20Nene%20Valley%20Railway%20-%20geograph.org.uk%20-%207277181.jpg?width=1024"},{"name":"Mid-Norfolk Railway","rarity":"common","id":"mid-norfolk-railway","subtitle":"Heritage Railroads & Companies","details":"Railway between Dereham and Wymondham in Norfolk, first opened in 1847 and running through the rural heart of the county and its market towns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mid-Norfolk%20Railway%2C%20East%20Dereham%20-%20geograph.org.uk%20-%202344158.jpg?width=1024"},{"name":"North Norfolk Railway","rarity":"common","id":"north-norfolk-railway","subtitle":"Heritage Railroads & Companies","details":"Railway called the Poppy Line between Sheringham and Holt in Norfolk, first opened in 1887 along the county's breezy north coast and farmland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ring%20Haw%20on%20its%20way%20to%20Holt%20-%20geograph.org.uk%20-%201369473.jpg?width=1024"},{"name":"Epping Ongar Railway","rarity":"common","id":"epping-ongar-railway","subtitle":"Heritage Railroads & Companies","details":"Railway on the former Central line branch between Epping and Ongar in Essex, running through farmland and woodland east of London.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dennis%20G%20Robinson%20loco%20%2B%20rolling%20stock%20Epping-Ongar-Railway%20North%20Weald%20Essex%20England.jpg?width=1024"},{"name":"Spa Valley Railway","rarity":"common","id":"spa-valley-railway","subtitle":"Heritage Railroads & Companies","details":"Railway between Tunbridge Wells West and Eridge, running through the Kent and Sussex border country of the wooded High Weald hills.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/01I07I2017%20SPA%20VALLEY%20RAILWAY%20Summer%20Steam%20Festival%20B3.jpg?width=1024"},{"name":"Isle of Wight Steam Railway","rarity":"common","id":"isle-of-wight-steam-railway","subtitle":"Heritage Railroads & Companies","details":"Railway between Smallbrook Junction and Wootton on the Isle of Wight, centred on its award-winning Victorian station at Havenstreet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Steam%20train%20and%20semaphore%20signal%20at%20Havenstreet%20-%20geograph.org.uk%20-%203461885.jpg?width=1024"},{"name":"Avon Valley Railway","rarity":"common","id":"avon-valley-railway","subtitle":"Heritage Railroads & Companies","details":"Railway between Oldland Common and Avon Riverside through Bitton, first opened in 1869 along the leafy River Avon valley near Bristol.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Preserved%20Sentinel%204w%20No.7492%20of%201928%20at%20Bitton%20Avon%20Valley%20Railway.jpg?width=1024"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
